package db

// query/ is generated by sqlc from schema.sql and queries/*.sql, with
// sqlc.json, never edited: change the schema or a query, then run
// `go generate ./server/db` in go/. CI fails when query/ differs from what
// they generate (gate G12). sqlc is the tool directive in go.mod, so its
// version is go.mod's; its SQLite engine needs no cgo.
//
//go:generate go tool sqlc generate -f sqlc.json
//go:generate go run ../../internal/spdxheader AGPL-3.0-or-later query/db.go query/models.go query/audit.sql.go query/auditexport.sql.go query/auth.sql.go query/authz.sql.go query/approvals.sql.go query/credentials.sql.go query/device.sql.go query/exposure.sql.go query/freeze.sql.go query/access.sql.go query/github.sql.go query/identities.sql.go query/installation.sql.go query/passkeys.sql.go query/people.sql.go query/projects.sql.go query/realtime.sql.go query/reports.sql.go query/requirements.sql.go query/schema_version.sql.go query/search.sql.go query/security.sql.go query/setup.sql.go query/values.sql.go query/valuewrites.sql.go query/webhooks.sql.go query/write.sql.go
